import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const stack = info.componentStack ?? null;
    console.error("[ErrorBoundary] Caught render error", {
      message: error.message,
      name: error.name,
      stack: error.stack,
      componentStack: stack,
    });
    this.props.onError?.(error, info);
    this.setState({ componentStack: stack });
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error, componentStack } = this.state;

    if (!error) return this.props.children;

    if (this.props.fallback) return this.props.fallback(error, this.reset);

    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.heading}>Something went wrong</h2>
        <pre style={styles.message}>{error.message}</pre>
        {componentStack && (
          <details style={styles.details}>
            <summary style={styles.summary}>Component stack</summary>
            <pre style={styles.stack}>{componentStack}</pre>
          </details>
        )}
        <button onClick={this.reset} style={styles.button}>
          Try again
        </button>
      </div>
    );
  }
}

const styles = {
  container: {
    padding: "1.25rem",
    border: "1px solid #f87171",
    borderRadius: "0.375rem",
    background: "#fff1f1",
    fontFamily: "inherit",
  },
  heading: {
    margin: "0 0 0.5rem",
    fontSize: "1rem",
    color: "#b91c1c",
  },
  message: {
    margin: "0 0 0.75rem",
    color: "#991b1b",
    whiteSpace: "pre-wrap" as const,
    fontSize: "0.875rem",
  },
  details: {
    margin: "0 0 0.75rem",
  },
  summary: {
    cursor: "pointer",
    fontSize: "0.8rem",
    color: "#6b7280",
  },
  stack: {
    margin: "0.5rem 0 0",
    fontSize: "0.75rem",
    color: "#374151",
    whiteSpace: "pre-wrap" as const,
    overflowX: "auto" as const,
  },
  button: {
    padding: "0.375rem 0.875rem",
    fontSize: "0.875rem",
    border: "1px solid #f87171",
    borderRadius: "0.25rem",
    background: "#fff",
    color: "#b91c1c",
    cursor: "pointer",
  },
} as const;

